-- Companies worked for (referenced by work experience entries)

create table "public"."companies" (
  "id" bigint primary key generated by default as identity,
  "logo" varchar,
  "name" varchar,
  "link" varchar,
  "is_active" boolean,
  "user" uuid,
  "order" smallint
);

alter table "public"."companies" add constraint "companies_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."companies" enable row level security;
create policy "Enable read access for all users" on "public"."companies" for select using (true);

grant all on "public"."companies" to postgres, anon, authenticated, service_role;
